steps.script:
var n = "R%d - %s vs %s - Movement" % [GameState.get_battle_round(), GameState.get_faction_name(1), GameState.get_faction_name(2)]
var md = SaveLoadManager.get_save_info(n).get("metadata", {})
var gs = md.get("game_state", {})
return "%d/%d/%d" % [int(gs.get("turn", -1)), int(gs.get("battle_round", -1)), int(md.get("preview", {}).get("battle_round", -1))]

var d = tree.root.get_node("/root/Main/SaveLoadDialog")
var want = "R%d - %s vs %s - Movement" % [GameState.get_battle_round(), GameState.get_faction_name(1), GameState.get_faction_name(2)]
for i in range(d.save_files_data.size()):
	if d.save_files_data[i].get("display_name", "") != want:
		continue
	var row = d.saves_list.get_item_text(i)
	var tip = d.saves_list.get_item_tooltip(i)
	if not row.begins_with("R2 - "):
		return "row did not start with the round: " + row
	if not ("Round: 2" in tip):
		return "tooltip round wrong: " + tip
	if not ("Phase: Movement" in tip):
		return "tooltip phase wrong: " + tip
	return "ok"
return "row not found for " + want

var d = tree.root.get_node("/root/Main/SaveLoadDialog")
var want = "R%d - %s vs %s - Movement" % [GameState.get_battle_round(), GameState.get_faction_name(1), GameState.get_faction_name(2)]
d.filter_input.text = want
d._on_filter_text_changed(want)
return d.save_files_data.size()
